def copy_paid_by(apps, schema_editor):
    # Cada gasto existente lo pagó una sola persona: el total
    Expense = apps.get_model('expenses', 'Expense')
    ExpensePayer = apps.get_model('expenses', 'ExpensePayer')
    ExpensePayer.objects.bulk_create(
        ExpensePayer(expense_id=expense.pk, user_id=expense.paid_by_id, amount=expense.amount)
        for expense in Expense.objects.all()
    )


def restore_paid_by(apps, schema_editor):
    Expense = apps.get_model('expenses', 'Expense')
    for expense in Expense.objects.all():
        payer = expense.payers.order_by('-amount').first()
        if payer:
            expense.paid_by_id = payer.user_id
            expense.save(update_fields=['paid_by'])


